def place_labels(points: list[dict], *, font: float, char: float,
                 gap: float) -> None:
    """마커 이름표가 서로 덮지 않게 자리를 고른다 — `points` 를 제자리에서 고친다.

    RS21 의 코어 셋이 50 km 안에 있다. 전체 지도처럼 전부 위에 얹으면 글자가
    글자를 덮어 어느 것이 어느 것인지 못 읽는다. 각 마커마다 위 → 오른쪽 →
    왼쪽 → 아래 → 네 귀퉁이 순으로 놓아 보고, 먼저 놓인 이름표·마커 어느 것과도
    안 겹치는 첫 자리를 준다. 다 겹치면 위에 둔다 — 안 그리는 것보다 겹치는
    편이 낫다. 상자는 `gap` 의 반만큼 부풀려 본다 — 딱 붙은 두 줄은 겹친 것과
    다름없이 읽힌다.

    글자 폭은 `char × 글자 수` 로 어림한다(km). 브라우저 글꼴을 서버가 모르니
    정확할 수 없고, 겹침을 판정할 만큼이면 된다.

    `points` 의 각 항목에 `lx`·`ly`(마커 기준 상대 좌표)와 `anchor` 를 더한다.
    **`anchor` 는 템플릿이 클래스로 옮긴다** — `.antmap .site .tag` 의 CSS 가
    `text-anchor: middle` 이라 속성으로 주면 CSS 에 진다.
    """
    taken = []          # 이미 차지한 상자 (x0, y0, x1, y1) — 마커 자체도 포함
    pad = gap / 2

    def box(p, dx, dy, anchor, w):
        x, y = p["x"] + dx, p["y"] + dy
        if anchor == "middle":
            x0, x1 = x - w / 2, x + w / 2
        elif anchor == "start":
            x0, x1 = x, x + w
        else:
            x0, x1 = x - w, x
        return (x0 - pad, y - font - pad, x1 + pad, y + pad)

    def hits(b):
        return any(not (b[2] < t[0] or b[0] > t[2] or b[3] < t[1] or b[1] > t[3])
                   for t in taken)

    for p in points:
        r = p["r"]
        taken.append((p["x"] - r, p["y"] - r, p["x"] + r, p["y"] + r))
    for p in points:
        w = char * len(p["label"])
        r = p["r"]
        d = r + gap
        mid = font * 0.38             # 글자 세로 가운데가 마커 높이에 오게
        # (dx, dy, anchor) — dy 는 글자 밑줄의 위치다
        tries = [(0, -d, "middle"),
                 (d, mid, "start"),
                 (-d, mid, "end"),
                 (0, d + font, "middle"),
                 (d * 0.7, -d * 0.7, "start"),
                 (d * 0.7, d * 0.7 + font, "start"),
                 (-d * 0.7, -d * 0.7, "end"),
                 (-d * 0.7, d * 0.7 + font, "end")]
        for dx, dy, anchor in tries:
            b = box(p, dx, dy, anchor, w)
            if not hits(b):
                break
        else:
            dx, dy, anchor = tries[0]
            b = box(p, dx, dy, anchor, w)
        taken.append(b)
        p["lx"], p["ly"], p["anchor"] = round(dx, 1), round(dy, 1), anchor


def context(sites: list[dict]) -> dict:
    """`data.map_points()` 의 지역 목록 → 이 지도가 그릴 것.

    **마커는 지역이 아니라 지점(코어)이다.** 전체 지도는 같은 지역의 코어가
    한 점에 겹쳐 지역으로 묶어 찍는데, 이 틀을 여는 이유가 바로 그 코어들을
    가르는 것이다. 이름표는 `<지역>-<지점>` (`Locality.__str__` 과 같다).

    틀 밖의 지점은 안 찍고 `outside` 로 낸다 — 화면이 "이 틀 밖: …" 으로 적는다.
    잘려서 안 보이는 것과 없는 것은 달라야 한다.
    """
    pts, outside = [], []
    for s in sites:
        for c in s["cores"]:
            code = f"{s['code']}-{c['code']}"
            if not in_frame(c["x"], c["y"]):
                outside.append(code)
                continue
            x, y = to_xy(c["x"], c["y"])
            pts.append({
                "label": code, "x": round(x, 1), "y": round(y, 1),
                "exact": c["exact"], "approx_note": s["approx_note"],
                "site": s["label"],
                "n_slides": c["n_slides"], "n_viewpoints": c["n_viewpoints"],
                "slug": c["slides"][0]["slug"],
                # 마커 반지름(km). 전체 지도의 70 을 MARK 로 줄인 것 — 이름표
                # 자리를 잴 때 마커가 차지하는 만큼을 알아야 한다
                "r": round(70 * MARK, 1),
            })
    # 글자 크기(km): base.html 의 `.rossmap .site .tag` 와 같은 값이어야 자리
    # 계산이 화면과 맞는다. 글자 폭은 크기의 0.6 배로 어림한다
    font = round(150 * MARK, 1)
    place_labels(pts, font=font, char=font * 0.6, gap=font * 0.35)
    vx, vy, vw, vh = VIEWBOX
    return {
        "viewbox": f"{vx} {vy} {vw} {vh}", "vb": VIEWBOX,
        "frame": FRAME,
        "land": LAND, "land_line": LAND_LINE,
        "shelf": SHELF, "shelf_line": SHELF_LINE,
        "lat_circles": LAT_CIRCLES, "lon_spokes": LON_SPOKES,
        "sea_labels": SEA_LABELS, "landmarks": LANDMARKS,
        "mark": MARK,
        "scale_bar": SCALE_BAR_KM, "scale_mid": SCALE_BAR_KM // 2,
        "scale_label": SCALE_BAR_LABEL,
        "scale_x": vx + round(vw * 0.05), "scale_y": vy + vh - round(vh * 0.06),
        "points": pts, "outside": outside,
        "any_approx": any(not p["exact"] for p in pts),
    }
